 "content": "from collections import Counter, deque


def components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            seen.add((r, c))
            q = deque([(r, c)])
            cells = []
            while q:
                p = q.popleft()
                cells.append(p)
                for nr, nc in ((p[0]-1,p[1]), (p[0]+1,p[1]), (p[0],p[1]-1), (p[0],p[1]+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr,nc))
                        q.append((nr,nc))
            result.append((color, cells))
    return result


def l_corner(cells):
    s = set(cells)
    r0, r1 = min(r for r,c in cells), max(r for r,c in cells)
    c0, c1 = min(c for r,c in cells), max(c for r,c in cells)
    # Detect an exact one-cell-wide L, with both arms at least 2 cells long.
    for r in (r0,r1):
        for c in (c0,c1):
            horiz = {(r,x) for x in range(c0,c1+1)}
            vert = {(x,c) for x in range(r0,r1+1)}
            if len(horiz & s) >= 2 and len(vert & s) >= 2 and horiz | vert == s:
                # Open diagonal quadrant is opposite to the directions occupied by the arms.
                dr = 1 if r == r0 else -1
                dc = 1 if c == c0 else -1
                return r, c, dr, dc
    return None


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    objs = components(grid)
    markers = []
    for i, (color, cells) in enumerate(objs):
        if color == bg or len(cells) < 4:
            continue
        corner = l_corner(cells)
        if corner:
            markers.append((i, color, cells, corner))
    out = [row[:] for row in grid]
    edits = []
    for idx, color, cells, (r,c,dr,dc) in markers:
        candidates = []
        for j, (other_color, other_cells) in enumerate(objs):
            if j == idx or other_color == bg:
                continue
            # The entire target component must lie in the marker's open diagonal quadrant.
            if all((rr-r)*dr > 0 and (cc-c)*dc > 0 for rr,cc in other_cells):
                distance = min((rr-r)**2 + (cc-c)**2 for rr,cc in other_cells)
                candidates.append((distance, -len(other_cells), j, other_cells))
        if candidates:
            _, _, j, target = min(candidates)
            edits.append((color, target))
    for color, target in edits:
        for r,c in target:
            out[r][c] = color
    return out


